    "overdue": true,
    "search": "n",
    "latitude": -90,
    "longitude": -179,
    "radio_km": 17,
    "per_page": 15
};

fetch(url, {
    method: "GET",
    headers,
    body: JSON.stringify(body),
}).then(response =&gt; response.json());</code></pre>                                        </div>
